var res = new List<object>();
var hostLevels = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().ToDictionary(l => l.Name, l => l.Elevation);
foreach (var li in new FilteredElementCollector(doc).OfClass(typeof(RevitLinkInstance)).Cast<RevitLinkInstance>()) {
  var nm = doc.GetElement(li.GetTypeId()).Name;
  if (!(nm.Contains("Building 03") || nm.Contains("STR-0010") || nm.Contains("0000_Datum") || nm.Contains("Building 01"))) continue;
  var ld = li.GetLinkDocument(); if (ld == null) { res.Add(new { nm, status = "not loaded" }); continue; }
  var t = li.GetTotalTransform();
  var cmp = new FilteredElementCollector(ld).OfClass(typeof(Level)).Cast<Level>().Where(l => hostLevels.ContainsKey(l.Name))
    .Select(l => new { l.Name, deltaMm = Math.Round((t.OfPoint(new XYZ(0,0,l.Elevation)).Z - hostLevels[l.Name]) * 304.8, 1) }).ToList();
  res.Add(new { nm, sameSharedSite = ld.ActiveProjectLocation.Name, offsetXYmm = new { x = Math.Round(t.Origin.X*304.8,1), y = Math.Round(t.Origin.Y*304.8,1), z = Math.Round(t.Origin.Z*304.8,1) }, rotDeg = Math.Round(Math.Atan2(t.BasisX.Y, t.BasisX.X)*180/Math.PI,3), levelDeltas = cmp });
}
return res;
